{
  "story": "Why does recursive factorial stop calling itself? Follow the stack as each call waits for a smaller input. The base case returns without another call. Then the waiting calls finish, and their frames leave the stack.",
  "aha": {
    "stateId": "base-case",
    "observation": "The base case returns 1 without another call, stopping stack growth and allowing waiting calls to finish."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "steps",
      "kind": "step-rail",
      "presentation": "Use the approved card shell and algorithm composition. Keep explanation and instructions above the experiment. Show compact step labels and highlight the current state. The rail owns progress; its index is not elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "call-stack",
      "kind": "fixed-picture",
      "presentation": "Arrange fixed stack slots vertically, newest above oldest. Highlighted slots are live frames; muted slots are inactive references, not stack contents. Each transition adds or removes at most one live frame. Keep frame names readable in every state.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "current-frame",
      "kind": "active-callout",
      "presentation": "Anchor beside the current frame without covering another slot. Identify its action; leave calculated values in the readouts. At completion, anchor beside the original frame's inactive slot.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "stack-evidence",
      "kind": "value-readout",
      "presentation": "Show live-frame count, evaluation, and status below the picture. Count highlighted frames; calculate returns from the same fixed input. Use exact integers, with frames as the count unit and no rounding. Assume nonnegative integer inputs, one frame per call, and no tail-call optimization. Fix the starting argument at three; define zero factorial as one. A returning frame leaves before its caller resumes.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "Recursion step",
      "items": "variant.states",
      "presentation": "Use Previous and Next, retaining those names when disabled at boundaries. Default to the first state; advance one state per action. Bounds are the first and last listed states. Every state persists until learner action, including base-case. Reference captures show base-case. Provide accessible names, visible focus, and keyboard operation. Parameter-control budget: zero; navigation and reset are separate."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide an accessible name, visible focus, and keyboard operation."
    }
  ],
